import unittest,re
from tools.kjv_archive import load_register,read
class HebrewsTestedPriesthoodTests(unittest.TestCase):
 def test_tested_priesthood_and_anchor(self):
  prior,_=load_register('0.10-kjv.259');lang,manifest=load_register('0.10-kjv.260')
  self.assertEqual(prior.lexicon,{k:lang.lexicon[k] for k in prior.lexicon})
  for attr in ('pairs','suffix','prefix','possessors','roman'):self.assertEqual(getattr(prior,attr),getattr(lang,attr))
  cases={c['id'].removeprefix('hebrews-'):c for c in read(lang.folder/'hebrews-tested-priesthood-and-anchor-cases.json')};self.assertEqual(len(cases),50)
  for c in cases.values():
   r=lang.compile(c['analysis']);self.assertEqual(c['expectedText'],r['text']);self.assertEqual(c['expectedGloss'],r['gloss']);self.assertNotIn('!',r['text'])
   self.assertFalse({'one','matter','worship'}&set(r['keys']))
  anchors={'4:1': ['to wesg into his/rest:ev enter:ev promise', 'any of you it:a reach:neg:inf seem:should'], '4:2': ['to wesg kjv_gospel proclaim:psv:pa', 'word they:a benefit:neg:pa', 'with faith in they who it hear:pa mix:psv:neg:pp'], '4:3': ['wesg who believe:perf into rest:ev enter:pr', 'ipl in mypl/wrath swear:perf if they', 'world kjv_foundation finish:psv:pa'], '4:4': ['of seven:ord day', 'god seven:ord day from all his/work:pl'], '4:5': ['if they into mypl/rest:ev enter:fu'], '4:6': ['some into it enter:must', 'first proclaim:psv:pa', 'because believe:neg:ev'], '4:7': ['particular day appoint:pr', 'in kjv_david', 'today if you his/voice', 'hard:caus:neg:imp'], '4:8': ['kjv_jesus_rest_hebrews to they rest:ev', 'afterward of another day speak:neg:should'], '4:9': ['to god people rest:ev remain:pr'], '4:10': ['from his/own work:pl cease:perf', 'as god from his/own work:pl'], '4:11': ['wesg into that rest:ev enter:inf labour:opt', 'same believe:neg:ev example'], '4:12': ['god word alive and powerful', 'two edge sword', 'kjv_soul and spirit', 'kjv_joint:pl and marrow', 'intention:pl distinguish:ag'], '4:13': ['any creature', 'all thing:pl kjv_nakedness:adj and open:psv:pp', 'he with who wesg relation'], '4:14': ['great high priest', 'kjv_jesus_matthew god son', 'ourone/acknowledge:ev'], '4:15': ['ourone/weakness:pl kjv_sympathize_hebrews:neg:can have:neg:pr', 'like wesg kjv_tempt_trial_hebrews:psv:pa yet without sin'], '4:16': ['wesg bold:adv to grace throne', 'mercy obtain:may', 'in need time help:inf grace'], '5:1': ['from among man:pl', 'to god belong:pr', 'gift:pl and kjv_sacrifice:pl'], '5:2': ['on ignorance:adj', 'out of way', 'he himself also with weakness'], '5:3': ['as for people so also for himself', 'for sin:pl offer:should'], '5:4': ['no man this honour to himself', 'by god call:psv:pr as kjv_aaron'], '5:5': ['himself glorify:neg:pa', 'thou mypl/son', 'today ipl thou:a beget:perf'], '5:6': ['thou forever priest', 'kjv_melchisedec_hebrews kjv_priestly_order_hebrews'], '5:7': ['his/flesh day:pl', 'strong cry:ev and tear:pl', 'from death save:inf', 'in that he fear:pa hear:psv:pa'], '5:8': ['though he son be:pa', 'suffer:pa obey:ev learn:pa'], '5:9': ['perfect make:psv:pp', 'all they who he:a obey:pr', 'kjv_author_salvation_hebrews'], '5:10': ['by god high priest', 'kjv_melchisedec_hebrews kjv_priestly_order_hebrews'], '5:11': ['wesg many thing:pl say:inf', 'utter:inf hard', 'you hearing dull'], '5:12': ['person you:a again', 'kjv_oracle_saying_acts:pl first kjv_elementary_principle_hebrews:pl', 'milk and not kjv_solid_food_hebrews'], '5:13': ['every person who milk use:pr', 'skill:neg:adj', 'he kjv_infant'], '5:14': ['kjv_solid_food_hebrews', 'because use:ev their/sense:pl', 'kjv_exercise_training_timothy:psv:perf'], '6:1': ['kjv_christ_title doctrine kjv_elementary_principle_hebrews:pl', 'wesg to perfect:ev', 'from dead work:pl repent:ev and towards god faith'], '6:2': ['kjv_baptize:ev:pl doctrine', 'hand:pl on lay:ev', 'dead:pl kjv_resurrection', 'eternal judgment'], '6:3': ['wesg do:fu if god permit:pr'], '6:4': ['once light:caus:psv:pa', 'heaven:adj gift taste:perf', 'kjv_holy_spirit_title share:cv person:pl', 'impossible be:pr'], '6:5': ['god good word', 'world which come:pr power:pl taste:perf'], '6:6': ['if they away fall:fu', 'again to repent:ev renew:inf', 'to themselves god son again kjv_crucify:pr'], '6:7': ['rain that on it often come:pr', 'by who it kjv_till_land:psv:pr', 'from god bless:ev'], '6:8': ['thorn:pl and kjv_brier:pl forth bring:pr', 'to curse:ev near', 'end burn:psv:inf'], '6:9': ['wesg of you better thing:pl', 'salvation accompany:pr', 'though wesg thus speak:pr'], '6:10': ['your/work and love labour', 'kjv_righteous:neg:adj be:neg:pr', 'serve:perf and serve:pr'], '6:11': ['wesg that every person of you', 'same kjv_diligent:ev', 'hope full assurance until end'], '6:12': ['lazy be:neg:may', 'through faith and patience promise:pl inherit:pr'], '6:13': ['god to kjv_abraham', 'by no greater swear:can:pa', 'by himself swear:pa'], '6:14': ['kjv_multiply:caus:cv ipl thou:a kjv_multiply:caus:fu', 'bless:cv ipl thou:a bless:fu'], '6:15': ['after patiently endure:perf', 'promise obtain:pa'], '6:16': ['by greater swear:pr', 'oath to they all strife end'], '6:17': ['promise heir:pl his/counsel change:neg:ev', 'by oath it confirm:pa'], '6:18': ['two change:neg:adj thing:pl', 'for god kjv_lie_false:inf impossible', 'hope before wesg set:psv:pp'], '6:19': ['wesg as kjv_soul kjv_anchor_hope_hebrews', 'sure and kjv_steadfast', 'within kjv_vail_partition'], '6:20': ['for wesg before run:cv person even kjv_jesus_matthew', 'forever high priest', 'kjv_melchisedec_hebrews kjv_priestly_order_hebrews']}
  for ref,parts in anchors.items():
   for part in parts:self.assertIn(part,cases[ref.replace(':','-')]['analysis'])
  self.assertIn('if they into mypl/rest:ev enter:fu',cases['4-3']['analysis'])
  self.assertEqual(cases['4-4']['analysis'].count('seven:ord'),2)
  self.assertIn('kjv_jesus_rest_hebrews',cases['4-8']['analysis'])
  self.assertIn('god word alive and powerful',cases['4-12']['analysis'])
  self.assertIn('kjv_sympathize_hebrews:neg:can have:neg:pr',cases['4-15']['analysis'])
  self.assertIn('in that he fear:pa hear:psv:pa',cases['5-7']['analysis'])
  self.assertIn('kjv_solid_food_hebrews',cases['5-14']['analysis'])
  self.assertIn('kjv_baptize:ev:pl doctrine',cases['6-2']['analysis'])
  self.assertIn('impossible be:pr',cases['6-4']['analysis'])
  self.assertIn('if they away fall:fu',cases['6-6']['analysis'])
  self.assertIn('kjv_multiply:caus:cv ipl',cases['6-14']['analysis'])
  self.assertIn('two change:neg:adj thing:pl',cases['6-18']['analysis'])
  self.assertIn('within kjv_vail_partition',cases['6-19']['analysis'])
  self.assertEqual(len(set(lang.lexicon)-set(prior.lexicon)),8)
  self.assertEqual(manifest['baseForgeHead'],read(prior.folder/'manifest.json')['forgeHead'])
